INSERT INTO `audit_temuan` VALUES ('AT2407-001','CA2407-002','BS2407-001','2024-07-19','','0','2024-07-19 17:27:57',2,NULL,NULL),('AT2407-002','CA2407-003','BS2407-002','2024-07-22','','0','2024-07-22 03:08:50',82,NULL,NULL),('AT2408-001','CA2407-001','BS2407-001','2024-08-22','','0','2024-08-22 16:35:18',82,NULL,NULL),('AT2408-002','CA2408-001','BS2408-001','2024-08-26','Audit SMK3 PP 50/2012','0','2024-08-26 12:23:35',22,NULL,NULL),('AT2408-003','CA2408-002','BS2408-004','2024-08-28','','0','2024-08-28 21:19:14',82,NULL,NULL),('AT2408-004','CA2408-003','BS2408-004','2024-08-28','','0','2024-08-28 21:30:23',82,NULL,NULL),('AT2409-001','CA2409-001','BS2407-001','2024-09-26','','0','2024-09-26 11:00:45',82,NULL,NULL),('AT2409-002','CA2409-002','BS2409-003','2024-09-26','','0','2024-09-26 11:13:48',82,NULL,NULL),('AT2409-003','CA2409-004','BS2409-003','2024-09-26','IATF 16949:2016','0','2024-09-26 14:03:06',14,NULL,NULL),('AT2409-004','CA2409-003','BS2409-005','2024-09-30','','0','2024-09-30 20:25:37',82,NULL,NULL),('AT2409-005','CA2409-005','BS2409-006','2024-09-30','','0','2024-09-30 20:57:30',73,NULL,NULL),('AT2409-006','CA2409-006','BS2408-004','2024-09-30','ISO 45001:2018','0','2024-09-30 21:40:42',22,NULL,NULL),('AT2409-007','CA2409-007','BS2408-004','2024-09-30','Emergency preparedness & response is not fully effective.  \'- Emergency Simulation plan schedule 2023: fire, earthquakes, explosion, riots, food poison, chemical spilled, pollution, but only the Fire Simulation will be carried out on December 21 2023. The others emergency simulation was not carried out and there is no explanation and corrective action.\r\n- In the fire emergency situation simulation, there is no target response time for fire extinguishing, evacuation, fire brigade arrival, ambulance arrival and other response times. Response time is only for the entire simulation. The organization need to have a target response time compared to the actual one in the simulation. So we will know whether the simulation is successful according to the target or not.','0','2024-09-30 22:05:34',28,NULL,NULL);
