  `category` enum('1','2','3') DEFAULT NULL,
  `process` varchar(100) DEFAULT NULL,
  `auditee` varchar(100) DEFAULT NULL,
  `auditor` varchar(15) DEFAULT NULL,
  `auditor_internal` varchar(10) DEFAULT NULL,
  `consultant` varchar(10) DEFAULT NULL,
  `status` enum('0','1') DEFAULT '1',
  `created_at` datetime DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `modified_at` datetime DEFAULT NULL,
  `modified_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `audit_id` (`audit_id`) USING BTREE,
