DROP TABLE IF EXISTS `directory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `directory` (
  `id` varchar(20) NOT NULL,
  `parent_id` varchar(20) DEFAULT NULL,
  `name` varchar(100) DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `flag_type` enum('FILE','FOLDER','LINK') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'FOLDER',
  `link` text,
  `doc` varchar(255) DEFAULT NULL,
  `file_name` varchar(100) DEFAULT NULL,
  `ext` varchar(5) DEFAULT NULL,
  `active` enum('Y','N') DEFAULT 'Y',
  `size` float DEFAULT NULL,
  `flag_record` enum('N','Y') DEFAULT 'N',
  `company_id` int(11) DEFAULT NULL,
  `prepared_by` int(11) DEFAULT NULL,
  `reviewer_id` int(11) DEFAULT NULL,
  `approval_id` int(11) DEFAULT NULL,
  `distribute_id` varchar(100) DEFAULT NULL,
  `status` enum('OPN','REV','COR','APV','DEL','PUB') DEFAULT 'OPN',
  `reviewed_by` int(11) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `picture` varchar(255) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `modified_by` int(11) DEFAULT NULL,
  `modified_at` datetime DEFAULT NULL,
  `number` varchar(255) DEFAULT NULL,
  `determination_date` date DEFAULT NULL,
  `about` varchar(150) DEFAULT NULL,
  `doc_status` varchar(100) DEFAULT NULL,
  `publisher` varchar(100) DEFAULT NULL,
  `custome` enum('N','Y') DEFAULT 'N',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
