INSERT INTO `procedure_details` VALUES (1,1,'1','Direktur ','Direktur bersama jajaran Manajemen menetapkan Visi dan ukuran visi perusahaan untuk 3 tahun ke depan','Visi',NULL,'1',4,'2022-10-04 20:18:40',NULL,NULL,NULL,NULL),(2,1,'2','All Division Head','Setiap kepala divisi membuat tahapan target pencapaian per tahun untuk menuju ke Visi','Tahapan target pencapaian pertahun',NULL,'1',4,'2022-10-04 20:20:40',NULL,NULL,NULL,NULL),(3,3,NULL,'HR staff','Memeriksa permintaan karyawan','permintaan',NULL,'1',4,'2022-10-05 17:00:01',NULL,NULL,NULL,NULL),(4,4,'1','Sales','Terima permintaan penawaran dari customer','-',NULL,'1',15,'2022-10-10 11:39:20',15,'2022-10-10 11:39:33',NULL,NULL),(5,4,'2','Sales','Identifikasi permintaan customer apakah bisa dipenuhi atau tidak','-',NULL,'1',15,'2022-10-10 11:39:48',NULL,NULL,NULL,NULL),(6,4,'3 - 4','Sales','Jika permintaan customer tidak sesuai dengan lingkup bisnis sentral sistem, maka permintaan penawaran ditolak dan otomatis end/close','-',NULL,'1',15,'2022-10-10 11:40:06',NULL,NULL,NULL,NULL),(7,4,'5-7; 14','Sales','Jika bisa dipenuhi maka selanjutnya cek dulu apakah customer baru atau lama. Jika customer baru maka perlu menambahkan ke database customer metalsindo dengan menginput master customer dan tambahkan data spesifikasi customer pada CRCL, lalu lanjutkan dengan membuat penawaran baru','-',NULL,'1',15,'2022-10-10 11:40:31',NULL,NULL,NULL,NULL),(8,4,'8 - 10','Sales','Jika customer merupakan customer lama maka cek dulu apakah penawarannya sama dengan sebelumnya dan bisa dicopy. Jika bisa dicopy (repeat order), maka pilih penawaran yang akan dicopy pada list penawaran yang tersedia, lalu select action copy. ','-',NULL,'1',15,'2022-10-10 11:40:49',NULL,NULL,NULL,NULL),(9,4,'11 - 13','Sales','Edit data customer ataupun data material jika diperlukan, dan jadilah penawaran baru','-',NULL,'1',15,'2022-10-10 11:41:19',NULL,NULL,NULL,NULL),(10,4,'14','Sales','Untuk membuat penawaran baru bagi customer baru maupun customer lama yang tidak repeat order, maka pilih add untuk create penawaran baru','-',NULL,'1',15,'2022-10-10 11:41:36',NULL,NULL,NULL,NULL),(11,4,'15','Sales','Masukkan data detail terkait customer','-',NULL,'1',15,'2022-10-10 11:41:50',NULL,NULL,NULL,NULL),(12,4,'16-17','Sales','Klik add untuk input material yang ditawarkan dan tambahkan data detail terkait material tersebut','-',NULL,'1',15,'2022-10-10 11:42:23',NULL,NULL,NULL,NULL),(13,4,'18','Sales','Setelah material ditambahkan, maka akan muncul pricelist sebagai referensi untuk penentuan harga penawaran','-',NULL,'1',15,'2022-10-10 11:42:44',NULL,NULL,NULL,NULL),(14,4,'19','Sales','Masukkan harga penawaran yang sesuai ','-',NULL,'1',15,'2022-10-10 11:43:05',NULL,NULL,NULL,NULL),(15,4,'20','Sales','Kirim penawaran yang sudah dibuat dan sudah di setujui manajemen ke customer','-',NULL,'1',15,'2022-10-10 11:43:22',NULL,NULL,NULL,NULL),(16,4,'21','Sales','Apabila customer keberatan dengan harga yang diberikan, maka dapat dilakukan negosiasi','-',NULL,'1',15,'2022-10-10 11:43:36',NULL,NULL,NULL,NULL),(17,4,'22','Sales','Setelah dilakukan negosiasi, maka akan berakhir pada tiga pilihan yaitu deal, revisi, dan lost. ','-',NULL,'1',15,'2022-10-10 11:43:50',NULL,NULL,NULL,NULL),(18,4,'23 - 24','Sales','Jika customer tidak setuju dengan penawaran yang diberikan ataupun sebaliknya maka penawaran dikategorikan lost, pilih action edit pada program dan input keterangan lostnya','-',NULL,'1',15,'2022-10-10 11:44:07',NULL,NULL,NULL,NULL),(19,4,'25 - 26','Sales','Jika terdapat kekeliruan dan dibutuhkan revisi terhadap penawaran, maka pilih action edit pada program dan lakukan revisi/ubah penawaran. ','-',NULL,'1',15,'2022-10-10 11:44:27',NULL,NULL,NULL,NULL),(20,4,'27','Sales','Revisi penawaran dilakukan hingga mencapai proses deal antara customer dan sales, jadi kemungkinan dilakukan negosiasi secara berulang setelah adanya revisi penawaran','-',NULL,'1',15,'2022-10-10 11:44:46',NULL,NULL,NULL,NULL),(21,4,'28','Sales','Sedangkan jika customer setuju dengan penawaran yang sudah diterima, maka penawaran dikategorikan deal dan akan dikirimkan PO ke sales','-',NULL,'1',15,'2022-10-10 11:45:03',NULL,NULL,NULL,NULL),(22,4,'29 - 30','Sales','Buat SPK Marketing baru berdasarkan PO dari customer dengan klik Add pada program dan input PO, harga deal, dan qty','-',NULL,'1',15,'2022-10-10 11:45:18',NULL,NULL,NULL,NULL),(23,4,'31','Sales','Jika sudah oke maka selanjutnya lakukan approval pada SPK marketing yang telah dibuat','-',NULL,'1',15,'2022-10-10 11:45:31',NULL,NULL,NULL,NULL),(24,4,'32 - 33','Sales','Setelah SPK marketing approve, maka status penawaran otomatis berubah jadi closed dan penawaran siap release ke proses lanjutnya yaitu material planning','-',NULL,'1',15,'2022-10-10 11:45:46',NULL,NULL,NULL,NULL),(25,5,'1','Planner','Tentukan SPK marketing yang akan diproses ','-',NULL,'1',15,'2022-10-10 13:13:30',15,'2022-10-10 13:13:38',NULL,NULL),(26,5,'2 - 3 ','Planner','Pelajari SPK marketing yang telah dipilih, jika terdapat ketidakcocokan terhadap material yang dipilih oleh marketing, maka ajukan usulan ganti/tambah material di menu penjualan','-',NULL,'1',15,'2022-10-10 13:15:11',NULL,NULL,NULL,NULL),(27,5,'4','Marketing','Input kategori revisi dan alasan pengajuan revisi','-',NULL,'1',15,'2022-10-10 13:15:26',NULL,NULL,NULL,NULL),(28,5,'5','Marketing','Marketing memproses approval pengajuan perubahan material yang diajukan planner','-',NULL,'1',15,'2022-10-10 13:15:38',NULL,NULL,NULL,NULL),(29,5,'6','Marketing','Marketing mengganti material sesuai request planner','-',NULL,'1',15,'2022-10-10 13:15:50',NULL,NULL,NULL,NULL),(30,5,'7','Planner','Jika telah terjadi kecocokan material, maka lanjut ke proses pemilihan stock berdasarkan stok yang ada','-',NULL,'1',15,'2022-10-10 13:16:04',NULL,NULL,NULL,NULL),(31,5,'8','Planner','Cek stok finish good (FG) yang tersedia yang sesuai SPK','-',NULL,'1',15,'2022-10-10 13:16:17',NULL,NULL,NULL,NULL),(32,5,'9-11','Planner','Jika ada FG yang sesuai, lalu pilih FG dengan width yang dibutuhkan sesuai SPK. Save untuk konfirmasi pemilihan FG, dan setelah disimpan maka akan terjadi perpindahan stok FG ke stok booking','-',NULL,'1',15,'2022-10-10 13:16:36',NULL,NULL,NULL,NULL),(33,5,'12','Planner','Jika tidak ada FG yang sesuai SPK, maka cek stok material yang tersedia ','-',NULL,'1',15,'2022-10-10 13:17:08',NULL,NULL,NULL,NULL),(34,5,'13','Planner','Jika ada material yang cocok dan sesuai SPK, maka langsung simpan untuk mengkonfirmasi pemilihan material secara otomatis','-',NULL,'1',15,'2022-10-10 13:17:26',NULL,NULL,NULL,NULL),(35,5,'14','Planner','Lakukan approve stock untuk stock FG yang telah dipilih maupun untuk perencanaan penggunaan material yang ada','-',NULL,'1',15,'2022-10-10 13:17:38',NULL,NULL,NULL,NULL),(36,5,'15','Planner','Setelah approve stock, maka otomatis data planning akan masuk ke laman next proses yaitu production planning pada modul production','-',NULL,'1',15,'2022-10-10 13:17:53',NULL,NULL,NULL,NULL),(37,5,'16 - 17','Planner','Jika tidak ada stock material yang tersedia, maka cek PO pada list purchase order di menu purchase apakah ada yg sesuai SPK','-',NULL,'1',15,'2022-10-10 13:18:12',NULL,NULL,NULL,NULL),(38,5,'18 - 19 ','Planner','Jika tidak terdapat PO yang sesuai SPK, maka buat PR dengan cara klik action create PR pada menu planning sehingga nantinya akan diproses oleh departemen purchasing','-',NULL,'1',15,'2022-10-10 13:18:30',NULL,NULL,NULL,NULL),(39,5,'20 - 21','Planner','Namun, jika terdapat PO yang sesuai SPK, maka monitor kedatangan material, dan saat material datang akan masuk ke warehouse material sehingga dapat dilanjutkan ke next process yaitu production planning','-',NULL,'1',15,'2022-10-10 13:18:46',NULL,NULL,NULL,NULL),(40,8,'1','Planner','Atur schedule produksi','-',NULL,'1',15,'2022-10-10 14:16:39',15,'2022-10-10 14:16:45',NULL,NULL),(41,8,'2','Planner','Tentukan sumber sesuai dengan yang telah dipilih pada planning sebelumnya apakah ingin mengambil dari finish good ataukah dari material jika memang tidak ada stock finish goodnya','-',NULL,'1',15,'2022-10-10 14:16:57',NULL,NULL,NULL,NULL),(42,8,'3','Planner','Jika memilih sumber dari finish good, maka pilih SPK Booking ','-',NULL,'1',15,'2022-10-10 14:17:07',NULL,NULL,NULL,NULL),(43,8,'4 - 6','Planner','Klik add untuk membuat SPK Produksi baru dan pilih FG yang akan dipakai. Lalu tambahkan detail terkait prosesnya','-',NULL,'1',15,'2022-10-10 14:17:24',NULL,NULL,NULL,NULL),(44,8,'7','Planner','Setelah disave, maka SPK produksi yang baru dibuat akan muncul pada list SPK produksi','-',NULL,'1',15,'2022-10-10 14:17:38',NULL,NULL,NULL,NULL),(45,8,'8','Planner','Jika memilih sumber dari material, maka pilih SPK reguler','-',NULL,'1',15,'2022-10-10 14:17:52',NULL,NULL,NULL,NULL),(46,8,'9 - 11','Planner','Klik add untuk membuat SPK Produksi baru dan pilih FG yang akan dipakai. Lalu tambahkan detail terkait prosesnya','-',NULL,'1',15,'2022-10-10 14:18:06',NULL,NULL,NULL,NULL),(47,8,'12','Planner','Setelah disave, maka SPK produksi yang baru dibuat akan muncul pada list SPK produksi','-',NULL,'1',15,'2022-10-10 14:18:21',NULL,NULL,NULL,NULL),(48,8,'13 - 16','Planner','Cek dulu SPK Produksi yang telah dibuat apakah masih ada yang perlu diedit atau tidak. Jika ada, maka klik action edit lalu edit SPK. Jika tidak ada, maka turunkan SPK produksinya','-',NULL,'1',15,'2022-10-10 14:18:43',NULL,NULL,NULL,NULL),(49,8,'17','Planner','Untuk SPK reguler yang menggunakan material, lanjut ke next proses yaitu produksi ','-',NULL,'1',15,'2022-10-10 14:18:59',NULL,NULL,NULL,NULL),(50,8,'18 - 19 ','Planner','Setelah SPK Produksi dibuat, maka selanjutnya create LHP material dan waktu. Jika berasal dari material booking, maka input LHP material dan waktu pada submenu LHP Booking, sedangkan jika berasal dari FG, maka input LHP material dan waktu pada submenu LHP Slitting Finishgood','-',NULL,'1',15,'2022-10-10 14:19:20',NULL,NULL,NULL,NULL),(51,8,'20 - 25','Planner','Pada LHP maupun LHP Booking, tentukan apakah material memerlukan tambahan jasa slitting, jika iya maka pilih opsi Y pada LHP. Jika no maka pilih opsi N','-',NULL,'1',15,'2022-10-10 14:19:44',NULL,NULL,NULL,NULL),(52,8,'26 - 33','Planner','Setelah dilakukan penginputan terkait detail LHP, maka cek dan validasi apakah semua yang diinput sudah benar. Jika sudah yakin, maka lakukan approve LHP. Jika belum, maka lakukan edit data. Jika terjadi ketidak cocokan data dengan produksi maka kembalikan ke bagian SPK produksi dengan klik action back to produksi. Sistem serupa baik pada submenu Laporan Harian Produksi maupun pada submenu LHP booking ','-',NULL,'1',15,'2022-10-10 14:20:07',NULL,NULL,NULL,NULL),(53,8,'34 - 37','Planner','Jika memang terdapat kekeliruan dan data harus dikembalikan ke produksi, maka setelah klik back to produksi, input alasan pengembalian dan data akan kembali muncul pada list SPK Produksi. Sistem serupa baik pada submenu Laporan Harian Produksi maupun pada submenu LHP booking ','-',NULL,'1',15,'2022-10-10 14:20:39',NULL,NULL,NULL,NULL),(54,8,'38 - 39','Planner','Jika LHP approve, maka akan muncul pada list history produksi. Sistem serupa baik pada submenu Laporan Harian Produksi maupun pada submenu LHP booking ','-',NULL,'1',15,'2022-10-10 14:53:07',NULL,NULL,NULL,NULL),(55,8,'40 - 45','Planner','Jika sebelumnya memilih opsi N pada jasa slitting, maka proses pada bagian LHP telah selesai. Namun, jika memilih opsi Y pada jasa tambahan slitting maka setelah LHP diapprove harus masuk ke submenu LHP Slitting finishgood untuk input LHP slitting finishgoodnya, kemudian approve untuk konfirmasi. Sistem serupa baik pada submenu Laporan Harian Produksi maupun pada submenu LHP booking ','-',NULL,'1',15,'2022-10-10 14:53:29',NULL,NULL,NULL,NULL),(56,8,'46 - 47','Planner','Untuk melihat/memonitor progress order yang dilakukan, maka pilih submenu progress order, kemudian select customer dan selanjutnya akan muncul data terkait progress order yang berkaitan','-',NULL,'1',15,'2022-10-10 14:53:46',NULL,NULL,NULL,NULL),(57,10,'1','asdad','asdasd','asdasdas',NULL,'1',15,'2022-10-10 16:22:16',15,'2022-10-10 16:22:22',NULL,NULL),(58,17,'1','HR & Div Head','Mengidentifikasi kebutuhan karyawan','Form Permintaan Pengajuan Karyawan',NULL,'0',18,'2022-10-31 09:36:53',NULL,NULL,18,'2022-10-31 09:44:35'),(59,17,'02','HR Dept','Menentukan kandidat yang direkrut berdasarkan sumber internal atau eksternal ','-',NULL,'0',18,'2022-10-31 09:41:23',NULL,NULL,18,'2022-10-31 09:44:28'),(60,17,'01','HRD, Div Head & Direktur','Mengidentifikasi kebutuhan karyawan berdasarkan bisnis plan, penggantian karyawan dan manpower plan\r\n','[\"10635f48650ef5d\"]',NULL,'1',18,'2022-10-31 09:46:12',18,'2022-11-10 14:58:12',NULL,NULL),(61,17,'02','HRD & Div Head','Menetapkan job specification','[\"10635f48650ef5d\"]',NULL,'1',18,'2022-10-31 09:49:19',18,'2022-11-10 11:28:56',NULL,NULL),(62,17,'03','HR & Div Head','Menentukan sumber tenaga kerja (internal atau eksternal).\r\n\r\nInternal melalui proses mutasi karyawan. \r\nEksternal melalui pencarian kandidat dari \r\nekternal.\r\n','null',NULL,'0',18,'2022-10-31 09:51:58',18,'2022-11-10 11:26:39',18,'2022-11-10 11:28:32'),(63,17,'04','HRD','Melakukan proses pencarian karyawan baru dengan cara pemasangan iklan lowongan kerja melalui job portal dan media sosial','null',NULL,'0',18,'2022-10-31 09:54:47',18,'2022-11-10 11:27:37',18,'2022-11-10 11:28:29'),(64,17,'05','HR','Melakukan seleksi data pelamar sesuai standar yang telah ditentukan','Job Description dan Standar Kompetensi',NULL,'0',18,'2022-10-31 09:56:12',NULL,NULL,18,'2022-11-10 11:28:26'),(65,17,'06','HR','Pemanggilan dan mengatur jadwal tes kandidat by phone atau email dengan format yang telah ditentukan','-',NULL,'0',18,'2022-10-31 09:57:56',NULL,NULL,18,'2022-11-10 11:28:23'),(66,17,'07','HR','Melakukan psikotes dan interview oleh HR','Form Data Pelamar dan Form Interview ',NULL,'0',18,'2022-10-31 10:00:21',NULL,NULL,18,'2022-11-10 11:28:20'),(67,17,'08','HR','Interview oleh User','Form Data Pelamar dan Form In