--
-- Table structure for table `procedures`
--

DROP TABLE IF EXISTS `procedures`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `procedures` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nomor` varchar(30) DEFAULT NULL,
  `company_id` int(11) DEFAULT NULL,
  `name` varchar(500) DEFAULT NULL,
  `group_procedure` int(11) DEFAULT NULL,
  `object` text,
  `define` text,
  `performance` text,
  `scope` text,
  `sipocor` text,
  `link_video` text,
  `number` varchar(255) DEFAULT NULL,
  `pic` varchar(255) DEFAULT NULL,
  `description` text,
  `relate_doc` varchar(255) DEFAULT NULL,
  `supplier` text,
  `input` text,
  `process` text,
  `output` text,
  `customer` text,
  `objective` text,
  `risk` text,
  `mitigation` text,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `modified_by` int(11) DEFAULT NULL,
  `modified_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `image_flow_1` varchar(255) DEFAULT NULL,
  `image_flow_2` varchar(255) DEFAULT NULL,
  `image_flow_3` varchar(255) DEFAULT NULL,
  `flow_file` varchar(255) DEFAULT NULL,
  `prepared_by` int(11) DEFAULT NULL,
  `reviewer_id` int(11) DEFAULT NULL,
  `approval_id` int(11) DEFAULT NULL,
  `distribute_id` varchar(100) DEFAULT NULL,
  `status` enum('DFT','REV','COR','APV','PUB','DEL','RVI','HLD') DEFAULT 'DFT',
  `revision` int(11) DEFAULT NULL,
  `revision_date` datetime DEFAULT NULL,
  `efective_date` date DEFAULT NULL,
  `reviewed_by` int(11) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `number_publish` varchar(255) DEFAULT NULL,
  `review_del_by` int(11) DEFAULT NULL,
  `review_del_at` datetime DEFAULT NULL,
  `approve_del_by` int(11) DEFAULT NULL,
  `approve_del_at` datetime DEFAULT NULL,
  `deletion_status` enum('OPN','REV','APV','REJ') DEFAULT NULL,
  `revision_req_by` int(11) DEFAULT NULL,
  `revision_req_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=373 DEFAULT CHARSET=utf8mb4;
