DROP TABLE IF EXISTS `ref_regulations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ref_regulations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `reference_id` int(11) DEFAULT NULL,
  `regulation_id` int(11) DEFAULT NULL,
  `descriptions` varchar(255) DEFAULT NULL,
  `status` enum('OPN','DONE','CNL','PND') DEFAULT 'OPN',
  `created_at` datetime DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `modified_at` datetime DEFAULT NULL,
  `modified_by` int(11) DEFAULT NULL,
  `last_update` datetime DEFAULT NULL,
  `total_compliance` int(11) DEFAULT NULL,
  `total_not_compliance` int(11) DEFAULT NULL,
  `total_not_applicable` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

